```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.List;
import java.util.ArrayList;

public class CommandInjectionFixed {
    public void executePing(String userIp) throws Exception {
        // To fix this, we use ProcessBuilder and pass the command and arguments 
        // as a List of separate strings. This prevents the shell from 
        // interpreting metacharacters like ';' or '&' as command separators.
        List<String> command = new ArrayList<>();
        command.add("ping");
        command.add("-c");
        command.add("4");
        command.add(userIp); // The input is treated strictly as a single argument

        ProcessBuilder pb = new ProcessBuilder(command);
        Process process = pb.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
    }
}
```

